EmpBasic.TotalDeductionLabel	  ,
EmpBasic.NetTotalPayableMoneyLabel	  ,
EmpBasic.BankAccountLabel	  ,
EmpBasic.LaborSignatureLabel	  ,
EmpBasic.SignaturesLabel	  ,
EmpBasic.AuthoritiesLabel	  ,
