            ExcelEngine excelEngine = null;
            IApplication application = null;
            IWorkbook workbook = null;
            IWorksheet sheet1 = null;

            int xlsRow = 1, xlsCol = 1;
            string FactoryName = "";
            string CmpName = "";
            int _x = 0;
            double _basic = 0;
            double _netPay = 0;


            #endregion Variable

            try
            {
