        private void AddNewRow(DataTable dt, IEnumerable<PlantWiseSalaryRegisterSortingParameters> entities)
        {
            //var identity = (CustomIdentity)Thread.CurrentPrincipal.Identity;
            DataRow dr = dt.NewRow();

            foreach (var item in entities)
            {
                try
                {
                    dr["Id"] = item.Id;
                    dr["CompanyGroupId"] = item.CompanyGroupId;
                    dr["CompanyId"] = item.CompanyId;
                    dr["PlantId"] = item.PlantId;
                    dr["Parameter"] = item.Parameter;
                    dr["Sequence"] = item.Sequence;

                    dr["AddedBy"] = item.AddedBy;
                    dr["AddedDate"] = System.DateTime.Now.ToString();
                    dr["AddedFromIP"] = item.AddedFromIP;
                    dr["UpdatedBy"] = item.UpdatedBy;
                    dr["UpdatedDate"] = System.DateTime.Now.ToString();
                    dr["UpdatedFromIP"] = item.UpdatedFromIP;
                }
                catch (Exception ex)
                {
                    throw ex;
                }
            }


            dt.Rows.Add(dr);
        }

